// src/pages/FarmMap.jsx
import { useRef, useState, useEffect, useCallback } from "react";
import C from "../constants/colors";
import S from "../utils/storage";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";
import Input from "../components/ui/Input";
import Btn from "../components/ui/Btn";

const CROP_OPTIONS = [
  "Tomato","Rice","Wheat","Maize","Cotton","Onion","Potato","Brinjal","Okra",
  "Groundnut","Sugarcane","Turmeric","Banana","Mango","Coconut","Ragi","Bajra",
  "Toor Dal","Urad Dal","Moong Dal","Sesame","Green Chilli","Carrot","Cauliflower",
];
const SOIL_TYPES    = ["Red","Black","Loamy","Sandy","Clay","Alluvial"];
const FARM_STATUSES = ["Healthy","Disease Alert","Monitor","Harvested","Fallow"];

// ─── Crop requirements per acre ───────────────────────────────────────────────
// seeds: kg/acre | N/P/K: kg/acre | organic: tonnes/acre
// spacing: "row × plant cm" | waterLpD: litre/acre/day | duration: days to harvest
const CROP_REQUIREMENTS = {
  Tomato:       { seeds: 0.15, N: 120, P: 60,  K: 60,  organic: 10, spacing: "60×45 cm",  waterLpD: 2000, duration: 90,  unit: "kg",  seedUnit: "g" },
  Rice:         { seeds: 20,   N: 120, P: 60,  K: 60,  organic: 5,  spacing: "20×15 cm",  waterLpD: 6000, duration: 120, unit: "kg",  seedUnit: "kg" },
  Wheat:        { seeds: 40,   N: 120, P: 60,  K: 40,  organic: 5,  spacing: "22×5 cm",   waterLpD: 3000, duration: 120, unit: "kg",  seedUnit: "kg" },
  Maize:        { seeds: 8,    N: 120, P: 60,  K: 40,  organic: 6,  spacing: "60×25 cm",  waterLpD: 3500, duration: 90,  unit: "kg",  seedUnit: "kg" },
  Cotton:       { seeds: 1.5,  N: 100, P: 50,  K: 50,  organic: 8,  spacing: "90×60 cm",  waterLpD: 2500, duration: 180, unit: "kg",  seedUnit: "kg" },
  Onion:        { seeds: 8,    N: 100, P: 50,  K: 50,  organic: 12, spacing: "15×10 cm",  waterLpD: 2000, duration: 120, unit: "kg",  seedUnit: "kg" },
  Potato:       { seeds: 1200, N: 150, P: 80,  K: 100, organic: 15, spacing: "60×20 cm",  waterLpD: 3000, duration: 90,  unit: "kg",  seedUnit: "kg" },
  Brinjal:      { seeds: 0.2,  N: 120, P: 60,  K: 60,  organic: 10, spacing: "75×60 cm",  waterLpD: 2000, duration: 120, unit: "kg",  seedUnit: "g" },
  Okra:         { seeds: 5,    N: 100, P: 50,  K: 50,  organic: 8,  spacing: "45×30 cm",  waterLpD: 2000, duration: 60,  unit: "kg",  seedUnit: "kg" },
  Groundnut:    { seeds: 60,   N: 25,  P: 50,  K: 50,  organic: 5,  spacing: "30×10 cm",  waterLpD: 2500, duration: 120, unit: "kg",  seedUnit: "kg" },
  Sugarcane:    { seeds: 5000, N: 250, P: 100, K: 120, organic: 20, spacing: "90×30 cm",  waterLpD: 8000, duration: 365, unit: "kg",  seedUnit: "setts" },
  Turmeric:     { seeds: 800,  N: 60,  P: 30,  K: 60,  organic: 15, spacing: "45×30 cm",  waterLpD: 3000, duration: 240, unit: "kg",  seedUnit: "kg" },
  Banana:       { seeds: 1100, N: 200, P: 60,  K: 300, organic: 20, spacing: "1.8×1.5 m", waterLpD: 5000, duration: 365, unit: "kg",  seedUnit: "suckers" },
  Mango:        { seeds: 100,  N: 500, P: 250, K: 500, organic: 25, spacing: "10×10 m",   waterLpD: 2000, duration: 1825,unit: "kg", seedUnit: "plants" },
  Coconut:      { seeds: 60,   N: 500, P: 320, K: 1200,organic: 50, spacing: "7.5×7.5 m", waterLpD: 1500, duration: 2190,unit: "kg", seedUnit: "nuts" },
  Ragi:         { seeds: 5,    N: 60,  P: 30,  K: 30,  organic: 4,  spacing: "22×10 cm",  waterLpD: 1500, duration: 120, unit: "kg",  seedUnit: "kg" },
  Bajra:        { seeds: 3,    N: 80,  P: 40,  K: 40,  organic: 4,  spacing: "45×15 cm",  waterLpD: 1500, duration: 90,  unit: "kg",  seedUnit: "kg" },
  "Toor Dal":   { seeds: 12,   N: 20,  P: 50,  K: 30,  organic: 5,  spacing: "90×30 cm",  waterLpD: 1800, duration: 150, unit: "kg",  seedUnit: "kg" },
  "Urad Dal":   { seeds: 10,   N: 20,  P: 40,  K: 20,  organic: 4,  spacing: "30×10 cm",  waterLpD: 1500, duration: 90,  unit: "kg",  seedUnit: "kg" },
  "Moong Dal":  { seeds: 8,    N: 20,  P: 40,  K: 20,  organic: 4,  spacing: "30×10 cm",  waterLpD: 1500, duration: 65,  unit: "kg",  seedUnit: "kg" },
  Sesame:       { seeds: 2,    N: 30,  P: 25,  K: 25,  organic: 3,  spacing: "30×10 cm",  waterLpD: 1200, duration: 90,  unit: "kg",  seedUnit: "kg" },
  "Green Chilli":{ seeds: 0.5, N: 120, P: 60,  K: 60,  organic: 10, spacing: "60×45 cm",  waterLpD: 2000, duration: 90,  unit: "kg",  seedUnit: "g" },
  Carrot:       { seeds: 3,    N: 60,  P: 40,  K: 60,  organic: 8,  spacing: "30×10 cm",  waterLpD: 2000, duration: 90,  unit: "kg",  seedUnit: "kg" },
  Cauliflower:  { seeds: 0.4,  N: 120, P: 60,  K: 60,  organic: 12, spacing: "60×45 cm",  waterLpD: 2000, duration: 90,  unit: "kg",  seedUnit: "g" },
};

// Fertiliser conversions  (actual product to apply)
// Urea = 46% N → 1kg N needs 2.17kg Urea
// DAP  = 18% N + 46% P → primarily P source; 1kg P needs 2.17kg DAP
// MOP  = 60% K → 1kg K needs 1.67kg MOP
function calcRequirements(crop, acres) {
  const r = CROP_REQUIREMENTS[crop];
  if (!r || !acres || acres <= 0) return null;
  const a = parseFloat(acres);

  // Classification
  const sizeLabel =
    a < 1   ? "Small Plot (< 1 acre)"   :
    a < 5   ? "Medium Farm (1–5 acres)" :
    a < 15  ? "Large Farm (5–15 acres)" :
              "Commercial Farm (15+ acres)";

  // Raw nutrients
  const totalN = +(r.N * a).toFixed(1);
  const totalP = +(r.P * a).toFixed(1);
  const totalK = +(r.K * a).toFixed(1);

  // Actual fertiliser products
  const urea  = +(totalN * 2.17).toFixed(1);    // kg
  const dap   = +(totalP * 2.17).toFixed(1);    // kg
  const mop   = +(totalK * 1.67).toFixed(1);    // kg

  // Seeds
  const seedQty = r.seedUnit === "g"
    ? +((r.seeds * a) * 1000).toFixed(0) + " g"
    : +(r.seeds * a).toFixed(1) + " kg";

  // Organic
  const organicT = +(r.organic * a).toFixed(1);
  const organicB = +(organicT * 20).toFixed(1);   // 1 tonne ≈ 20 bags (50 kg bag)

  // Water
  const waterPerDay = +(r.waterLpD * a / 1000).toFixed(1); // kL/day

  // Estimated cost (rough Indian market rates 2024)
  const seedCost    = r.seedUnit === "g"
    ? Math.round((r.seeds * a * 1000) * 0.8)   // ₹0.8/g avg
    : Math.round(r.seeds * a * 80);             // ₹80/kg avg
  const fertCost    = Math.round((urea * 7) + (dap * 27) + (mop * 18));
  const organicCost = Math.round(organicT * 1200); // ₹1200/tonne FYM
  const totalCost   = seedCost + fertCost + organicCost;

  return {
    crop, acres: a, sizeLabel,
    seeds: seedQty,
    urea, dap, mop,
    totalN, totalP, totalK,
    organic: organicT, organicBags: organicB,
    waterPerDay,
    duration: r.duration,
    spacing: r.spacing,
    seedCost, fertCost, organicCost, totalCost,
  };
}

const TILE_LAYERS = {
  street: {
    url: "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",
    attribution: "© OpenStreetMap contributors",
    label: "🗺️ Map",
  },
  satellite: {
    url: "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}",
    attribution: "© Esri, Maxar, Earthstar Geographics",
    label: "🛰️ Satellite",
  },
};

async function reverseGeocode(lat, lon) {
  try {
    const res = await fetch(
      `https://nominatim.openstreetmap.org/reverse?format=json&lat=${lat}&lon=${lon}&zoom=18&addressdetails=1`,
      { headers: { "Accept-Language": "en" } }
    );
    return await res.json();
  } catch { return null; }
}

async function forwardSearch(query) {
  try {
    const base = "https://nominatim.openstreetmap.org/search?format=json&addressdetails=1&countrycodes=in&limit=8";

    const [structured, freetext] = await Promise.all([
      fetch(`${base}&city=${encodeURIComponent(query)}&state=Tamil+Nadu`, { headers: { "Accept-Language": "en" } }).then(r => r.json()).catch(() => []),
      fetch(`${base}&q=${encodeURIComponent(query + " Tamil Nadu")}`,     { headers: { "Accept-Language": "en" } }).then(r => r.json()).catch(() => []),
    ]);

    const merged = [...structured, ...freetext];

    const seen = new Set();
    const unique = merged.filter(r => {
      if (seen.has(r.place_id)) return false;
      seen.add(r.place_id);
      return true;
    });

    const q = query.toLowerCase();
    return unique.sort((a, b) => {
      const aName = (a.address?.city || a.address?.town || a.address?.village || a.display_name.split(",")[0]).toLowerCase();
      const bName = (b.address?.city || b.address?.town || b.address?.village || b.display_name.split(",")[0]).toLowerCase();
      const aExact = aName === q ? 0 : aName.startsWith(q) ? 1 : 2;
      const bExact = bName === q ? 0 : bName.startsWith(q) ? 1 : 2;
      if (aExact !== bExact) return aExact - bExact;

      const typeRank = { city: 0, town: 1, village: 2, suburb: 3, hamlet: 4 };
      const aRank = typeRank[a.type] ?? 5;
      const bRank = typeRank[b.type] ?? 5;
      return aRank - bRank;
    });
  } catch { return []; }
}

function formatAddr(data) {
  if (!data?.address) return null;
  const a     = data.address;
  const line1 = [a.hamlet, a.village, a.suburb, a.neighbourhood, a.road].filter(Boolean).join(", ")
    || data.display_name?.split(",")[0];
  const line2 = [a.town || a.city || a.county, a.state_district || a.district].filter(Boolean).join(", ");
  const line3 = [a.state, a.postcode].filter(Boolean).join(" – ");
  return { line1, line2, line3 };
}

// ─────────────────────────────────────────────────────────────────────────────
function FarmMap({ user, t, lang }) {
  const mapRef       = useRef(null);
  const pickerMapRef = useRef(null);
  const mapInst      = useRef(null);
  const pickerInst   = useRef(null);
  const tileRef      = useRef(null);
  const pickerTile   = useRef(null);
  const farmMarkers  = useRef({});
  const rgTimer      = useRef(null);
  const srTimer      = useRef(null);
  const mainSrTimer  = useRef(null);  // ← NEW: main map search debounce
  const searchInputRef = useRef(null); // auto-focus search on picker open

  const [loaded,          setLoaded]          = useState(false);
  const [farms,           setFarms]           = useState(() => Array.isArray(user?.farms) ? user.farms : []);
  const [pickerOpen,      setPickerOpen]       = useState(false);
  const [tileMode,        setTileMode]         = useState("street");
  const [confirmRemove,   setConfirmRemove]    = useState(null);
  const [analyseFarm,     setAnalyseFarm]      = useState(null); // farm being analysed

  // ── NEW: Main map search state ────────────────────────────────────────────
  const [mainSearch,      setMainSearch]       = useState("");
  const [mainResults,     setMainResults]      = useState([]);
  const [mainSearching,   setMainSearching]    = useState(false);
  const [mainShowSuggest, setMainShowSuggest]  = useState(false);
  const [mainFlownTo,     setMainFlownTo]      = useState(null); // last flown location name

  // Picker state
  const [pickerLoaded,    setPickerLoaded]     = useState(false);
  const [pinMoving,       setPinMoving]        = useState(false);
  const [detectedAddr,    setDetectedAddr]     = useState(null);
  const [rgLoading,       setRgLoading]        = useState(false);
  const [gpsStatus,       setGpsStatus]        = useState("idle");
  const [searchQuery,     setSearchQuery]      = useState("");
  const [searchResults,   setSearchResults]    = useState([]);
  const [searching,       setSearching]        = useState(false);
  const [showSuggestions, setShowSuggestions]  = useState(false);
  const [pickerCoords,    setPickerCoords]     = useState(null);
  const [locationAccuracy, setLocationAccuracy] = useState(null); // metres — null = unknown

  const [formFarm, setFormFarm] = useState({
    name: "", crop: CROP_OPTIONS[0], size: "", soilType: "Red", status: "Healthy",
  });

  // ── Language strings ──────────────────────────────────────────────────────
  const SEARCH_STRINGS = {
    en: {
      placeholder: "Search area, village, city, landmark…",
      searching:   "Searching…",
      notFound:    "No results found",
      flyingTo:    "Navigating to",
    },
    ta: {
      placeholder: "பகுதி, கிராமம், நகரம், இடம் தேடுக…",
      searching:   "தேடுகிறது…",
      notFound:    "முடிவுகள் இல்லை",
      flyingTo:    "செல்கிறது",
    },
    hi: {
      placeholder: "क्षेत्र, गांव, शहर, स्थान खोजें…",
      searching:   "खोज रहे हैं…",
      notFound:    "कोई परिणाम नहीं",
      flyingTo:    "जा रहे हैं",
    },
  };
  const SS = SEARCH_STRINGS[lang] || SEARCH_STRINGS.en;

  const TX = {
    title:       t?.("map.title")                || "Farm Map",
    subtitle:    t?.("map.subtitle")             || "GPS mapping of your farm plots",
    addPlot:     t?.("map.addPlot")              || "+ Add Farm",
    yourFarms:   t?.("map.yourFarms")            || "My Farm Plots",
    noFarms:     t?.("map.noFarms")              || "No farms added yet",
    addFirst:    t?.("map.addFirst")             || "Click '+ Add Farm' to start",
    area:        t?.("map.area")                 || "Area",
    crop:        t?.("map.crop")                 || "Crop",
    plotName:    t?.("map.plotName")             || "Plot Name",
    loading:     t?.("common.loading")           || "Loading map…",
    saveFarm:    t?.("save")                     || "Save Farm",
    cancel:      t?.("cancel")                   || "Cancel",
    acres:       t?.("common.acres")             || "acres",
    fieldConds:  "🌡️ Field Conditions Today",
    temp:        "Temperature",
    humidity:    t?.("dashboard.weatherLabel")    || "Humidity",
    pestRisk:    t?.("dashboard.pestAlert")       || "Pest Risk",
    diseaseRisk: t?.("dashboard.diseasePressure") || "Disease Risk",
    irrigation:  "Irrigation Need",
    ndvi:        "📡 NDVI Satellite Status",
    soilType:    "Soil Type",
    status:      "Status",
  };

  // ── NEW: Main map search handler ──────────────────────────────────────────
  const handleMainSearch = (val) => {
    setMainSearch(val);
    setMainFlownTo(null);
    clearTimeout(mainSrTimer.current);
    if (val.length < 2) { setMainResults([]); setMainShowSuggest(false); return; }
    setMainSearching(true);
    mainSrTimer.current = setTimeout(async () => {
      const results = await forwardSearch(val);
      setMainResults(results);
      setMainShowSuggest(true);
      setMainSearching(false);
    }, 400);
  };

  // ── NEW: Fly main map to selected result ──────────────────────────────────
  const selectMainResult = (r) => {
    const lat  = parseFloat(r.lat);
    const lon  = parseFloat(r.lon);
    const name = r.display_name.split(",")[0];

    if (mapInst.current) {
      mapInst.current.flyTo([lat, lon], 16, { animate: true, duration: 1.5 });
    }

    setMainSearch(name);
    setMainResults([]);
    setMainShowSuggest(false);
    setMainFlownTo(name);
  };

  // ── Load Leaflet ──────────────────────────────────────────────────────────
  useEffect(() => {
    if (document.querySelector("#leaflet-css")) {
      if (window.L) setLoaded(true);
      else {
        const w = setInterval(() => { if (window.L) { setLoaded(true); clearInterval(w); } }, 100);
        return () => clearInterval(w);
      }
      return;
    }
    const css    = document.createElement("link");
    css.id       = "leaflet-css"; css.rel = "stylesheet";
    css.href     = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";
    document.head.appendChild(css);
    const sc     = document.createElement("script");
    sc.src       = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";
    sc.onload    = () => setLoaded(true);
    sc.onerror   = () => console.warn("Leaflet failed");
    document.head.appendChild(sc);
  }, []);

  // ── View map init ─────────────────────────────────────────────────────────
  useEffect(() => {
    if (!loaded || !mapRef.current || mapInst.current) return;
    const L        = window.L;
    const fallLat  = user?.lat || 9.9252;
    const fallLon  = user?.lon || 78.1198;

    // Start at fallback; we'll fly to real GPS immediately below
    const map = L.map(mapRef.current, { zoomControl: true }).setView([fallLat, fallLon], 14);
    tileRef.current = L.tileLayer(TILE_LAYERS.street.url, {
      attribution: TILE_LAYERS.street.attribution, maxZoom: 21,
    }).addTo(map);

    // User dot marker — we keep a ref so we can move it when GPS resolves
    const userDotIcon = (pulsing) => L.divIcon({
      html: pulsing
        ? `<div style="position:relative;width:20px;height:20px">
             <div style="position:absolute;inset:0;border-radius:50%;background:rgba(26,122,58,.25);animation:gps-pulse 1.4s ease-out infinite"></div>
             <div style="position:absolute;top:3px;left:3px;width:14px;height:14px;border-radius:50%;background:${C.bg2||"#1a7a3a"};border:3px solid #fff;box-shadow:0 2px 8px rgba(0,0,0,.5)"></div>
           </div>
           <style>@keyframes gps-pulse{0%{transform:scale(1);opacity:.8}100%{transform:scale(2.8);opacity:0}}</style>`
        : `<div style="background:${C.bg2||"#1a7a3a"};width:14px;height:14px;border-radius:50%;border:3px solid #fff;box-shadow:0 2px 8px rgba(0,0,0,.5)"></div>`,
      iconSize:   [20, 20],
      iconAnchor: [10, 10],
      className:  "",
    });

    const userMarker = L.marker([fallLat, fallLon], { icon: userDotIcon(false) })
      .addTo(map)
      .bindPopup(`<b>📍 ${user?.name || "Your Location"}</b><br>${user?.district || ""}`);

    farms.forEach(f => { if (f?.lat && f?.lon) _addViewMarker(L, map, f); });
    mapInst.current = map;

    // ── Auto-locate: request GPS right away ──────────────────────────────
    if (navigator.geolocation) {
      // Show pulsing ring while waiting
      userMarker.setIcon(userDotIcon(true));

      navigator.geolocation.getCurrentPosition(
        pos => {
          const { latitude: gLat, longitude: gLon, accuracy } = pos.coords;

          // Move user dot to real position
          userMarker.setLatLng([gLat, gLon]);
          userMarker.setIcon(userDotIcon(false));
          userMarker.bindPopup(
            `<b>📍 ${user?.name || "You"}</b><br>` +
            `${user?.district || ""}<br>` +
            `<span style="font-size:10px;color:#888">GPS accuracy: ±${Math.round(accuracy)}m</span>`
          );

          // Blue accuracy circle
          if (map._gpsCircle) map._gpsCircle.remove();
          map._gpsCircle = L.circle([gLat, gLon], {
            radius: accuracy,
            color: "#1a7a3a", fillColor: "#1a7a3a",
            fillOpacity: 0.08, weight: 1.5, dashArray: "4 4",
          }).addTo(map);

          // Fly smoothly to real location
          map.flyTo([gLat, gLon], 16, { animate: true, duration: 1.6 });
        },
        () => {
          // Permission denied / timeout — silently keep fallback position
          userMarker.setIcon(userDotIcon(false));
        },
        { enableHighAccuracy: true, timeout: 12000, maximumAge: 0 }
      );
    }
  }, [loaded]); // eslint-disable-line

  // ── View map tile toggle ──────────────────────────────────────────────────
  useEffect(() => {
    const map = mapInst.current; const L = window.L;
    if (!map || !L) return;
    tileRef.current?.remove();
    tileRef.current = L.tileLayer(TILE_LAYERS[tileMode].url, {
      attribution: TILE_LAYERS[tileMode].attribution, maxZoom: 21,
    }).addTo(map);
  }, [tileMode]);

  // ── Picker map init ───────────────────────────────────────────────────────
  // Desktop browsers don't have GPS → never auto-run geolocation.
  // Instead: forward-geocode the user's saved district for a correct start,
  // then auto-focus search so they can type their exact location instantly.
  useEffect(() => {
    if (!pickerOpen || !loaded) return;
    const tid = setTimeout(async () => {
      if (!pickerMapRef.current || pickerInst.current) return;
      const L = window.L;

      // 1. Best known starting point priority:
      //    last saved farm → user profile coords → forward-geocode district → TN centre
      const lastFarm = farms.length > 0 ? farms[farms.length - 1] : null;
      let startLat = lastFarm?.lat ?? user?.lat ?? null;
      let startLon = lastFarm?.lon ?? user?.lon ?? null;
      let startZoom = lastFarm ? 16 : 14;

      // 2. If no coords stored, forward-geocode the user's district name
      if (!startLat && user?.district) {
        try {
          const res  = await fetch(
            `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(user.district + ", Tamil Nadu, India")}&limit=1`,
            { headers: { "Accept-Language": "en" } }
          );
          const data = await res.json();
          if (data[0]) {
            startLat  = parseFloat(data[0].lat);
            startLon  = parseFloat(data[0].lon);
            startZoom = 13;
          }
        } catch (_) { /* network error — use TN centre */ }
      }

      // Final fallback: Tamil Nadu geographic centre
      startLat = startLat ?? 10.8505;
      startLon = startLon ?? 77.0;

      const map = L.map(pickerMapRef.current, { zoomControl: false })
        .setView([startLat, startLon], startZoom);

      // moveend → always live-geocode the centre pin position
      map.on("movestart", () => setPinMoving(true));
      map.on("moveend", () => {
        setPinMoving(false);
        const { lat: la, lng: lo } = map.getCenter();
        setPickerCoords({ lat: la, lon: lo });
        clearTimeout(rgTimer.current);
        setRgLoading(true);
        rgTimer.current = setTimeout(async () => {
          const r = await reverseGeocode(la, lo);
          setDetectedAddr(r);
          setRgLoading(false);
        }, 400);
      });

      pickerTile.current = L.tileLayer(TILE_LAYERS[tileMode].url, {
        attribution: TILE_LAYERS[tileMode].attribution, maxZoom: 21,
      }).addTo(map);
      L.control.zoom({ position: "bottomright" }).addTo(map);

      pickerInst.current = map;
      setPickerLoaded(true);
      setGpsStatus("idle");
      setLocationAccuracy(null);

      // Geocode the starting position so address card shows immediately
      setRgLoading(true);
      setPickerCoords({ lat: startLat, lon: startLon });
      reverseGeocode(startLat, startLon).then(r => {
        setDetectedAddr(r);
        setRgLoading(false);
      });

      // Auto-focus the search bar after map renders
      setTimeout(() => searchInputRef.current?.focus(), 300);
    }, 80);
    return () => clearTimeout(tid);
  }, [pickerOpen, loaded]); // eslint-disable-line

  // ── Picker tile toggle ────────────────────────────────────────────────────
  useEffect(() => {
    const map = pickerInst.current; const L = window.L;
    if (!map || !L) return;
    pickerTile.current?.remove();
    pickerTile.current = L.tileLayer(TILE_LAYERS[tileMode].url, {
      attribution: TILE_LAYERS[tileMode].attribution, maxZoom: 21,
    }).addTo(map);
  }, [tileMode]);

  // ── Destroy picker on close ───────────────────────────────────────────────
  useEffect(() => {
    if (!pickerOpen && pickerInst.current) {
      pickerInst.current.remove();
      pickerInst.current = null;
      setPickerLoaded(false);
      setDetectedAddr(null);
      setPickerCoords(null);
      setSearchQuery("");
      setSearchResults([]);
      setShowSuggestions(false);
      setGpsStatus("idle");
      setLocationAccuracy(null);
    }
  }, [pickerOpen]);

  // ── GPS ───────────────────────────────────────────────────────────────────
  const handleGPS = useCallback(() => {
    if (!navigator.geolocation) { setGpsStatus("error"); return; }
    setGpsStatus("loading");
    navigator.geolocation.getCurrentPosition(
      pos => {
        setGpsStatus("done");
        pickerInst.current?.flyTo([pos.coords.latitude, pos.coords.longitude], 18, { animate: true, duration: 1.2 });
        setTimeout(() => setGpsStatus("idle"), 2500);
      },
      () => { setGpsStatus("error"); setTimeout(() => setGpsStatus("idle"), 2500); },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  }, []);

  // ── Picker search ─────────────────────────────────────────────────────────
  const handleSearchInput = val => {
    setSearchQuery(val);
    clearTimeout(srTimer.current);
    if (val.length < 3) { setSearchResults([]); setShowSuggestions(false); return; }
    setSearching(true);
    srTimer.current = setTimeout(async () => {
      const r = await forwardSearch(val);
      setSearchResults(r);
      setShowSuggestions(true);
      setSearching(false);
    }, 450);
  };

  const selectResult = r => {
    pickerInst.current?.flyTo([parseFloat(r.lat), parseFloat(r.lon)], 17, { animate: true, duration: 1 });
    setSearchQuery(r.display_name.split(",")[0]);
    setSearchResults([]);
    setShowSuggestions(false);
  };

  // ── Save farm ─────────────────────────────────────────────────────────────
  const confirmSave = () => {
    if (!formFarm.name || !formFarm.crop || !pickerCoords) return;
    const addr = formatAddr(detectedAddr);
    const farm = {
      id: Date.now(), ...formFarm,
      lat: pickerCoords.lat, lon: pickerCoords.lon,
      address: addr ? `${addr.line1}${addr.line2 ? ", " + addr.line2 : ""}` : "",
      addedOn: new Date().toLocaleDateString("en-IN"),
    };
    const updated = [...farms, farm];
    setFarms(updated);

    const users = S.get("users") || [];
    const idx   = users.findIndex(u => u.id === user?.id);
    if (idx >= 0) { users[idx].farms = updated; S.set("users", users); S.set("current_user", users[idx]); }

    if (mapInst.current && window.L) _addViewMarker(window.L, mapInst.current, farm);
    setFormFarm({ name: "", crop: CROP_OPTIONS[0], size: "", soilType: "Red", status: "Healthy" });
    setPickerOpen(false);
  };

  const _addViewMarker = (L, map, farm) => {
    const fc     = farm.status === "Healthy" ? "#1a7a3a" : farm.status === "Disease Alert" ? "#b83232" : "#c87010";
    const marker = L.marker([farm.lat, farm.lon], {
      icon: L.divIcon({
        html: `<div style="background:${fc};color:#fff;padding:4px 9px;border-radius:6px;font-size:11px;font-weight:600;white-space:nowrap;box-shadow:0 2px 8px rgba(0,0,0,.35)">${farm.crop}</div>`,
        className: "",
      }),
    }).addTo(map).bindPopup(
      `<b>${farm.name}</b><br>` +
      (farm.address ? `<span style="color:#555;font-size:11px">📍 ${farm.address}</span><br>` : "") +
      `Crop: ${farm.crop} · ${farm.size} ${TX.acres}<br>Status: ${farm.status}<br>` +
      `<span style="font-size:10px;color:#aaa">${farm.lat.toFixed(5)}, ${farm.lon.toFixed(5)}</span>`
    );
    farmMarkers.current[farm.id] = marker;
  };

  const removeFarm = id => {
    farmMarkers.current[id]?.remove();
    delete farmMarkers.current[id];
    const updated = farms.filter(f => f.id !== id);
    setFarms(updated);
    setConfirmRemove(null);
    const users = S.get("users") || [];
    const idx   = users.findIndex(u => u.id === user?.id);
    if (idx >= 0) { users[idx].farms = updated; S.set("users", users); S.set("current_user", users[idx]); }
  };

  const statusColor = { Healthy: C.bg2, "Disease Alert": C.red, Monitor: C.orange };
  const statusBg    = { Healthy: C.pale, "Disease Alert": "#fff0f0", Monitor: "#fff8ee" };
  const gpsLabel = {
    idle:    "📡 My Location",
    loading: "⏳ Locating…",
    done:    "✅ Located!",
    error:   "❌ Allow location in browser",
    poor:    "📡 Search your location",
  };
  const addr        = formatAddr(detectedAddr);

  const fieldConditions = [
    { label: TX.temp,        val: "32°C",          risk: "Low"    },
    { label: TX.humidity,    val: "72%",            risk: "Medium" },
    { label: TX.pestRisk,    val: "Moderate",       risk: "Medium" },
    { label: TX.diseaseRisk, val: "High",           risk: "High"   },
    { label: TX.irrigation,  val: "Tomorrow 6 AM", risk: ""       },
  ];

  // ── Analysis helpers (used inside main return) ────────────────────────────
  const analysisReq = analyseFarm ? calcRequirements(analyseFarm.crop, analyseFarm.size) : null;
  const AnalysisROW = ({ label, val, sub, color }) => (
    <div style={{
      display: "flex", justifyContent: "space-between", alignItems: "center",
      padding: "9px 0", borderBottom: `1px solid ${C.border || "#eee"}`,
    }}>
      <div>
        <div style={{ fontSize: 13, color: C.muted || "#888" }}>{label}</div>
        {sub && <div style={{ fontSize: 10.5, color: "#bbb", marginTop: 1 }}>{sub}</div>}
      </div>
      <div style={{ fontSize: 14, fontWeight: 700, color: color || C.text || "#222" }}>{val}</div>
    </div>
  );

  // ═══════════════════════════════════════════════════════════════════════════
  // PICKER SCREEN
  // ═══════════════════════════════════════════════════════════════════════════
  if (pickerOpen) {
    return (
      <div style={{ display: "flex", flexDirection: "column", minHeight: "100vh", background: "#f4f6f8" }}>
        <div style={{
          display: "flex", alignItems: "center", gap: 10,
          padding: "12px 16px", background: "#fff",
          borderBottom: "1px solid #e8e8e8",
          boxShadow: "0 2px 6px rgba(0,0,0,.08)", flexShrink: 0,
        }}>
          <button onClick={() => setPickerOpen(false)} style={{
            background: "none", border: "none", fontSize: 22, cursor: "pointer", color: "#333",
            lineHeight: 1, padding: "2px 6px 2px 0",
          }}>←</button>
          <div>
            <div style={{ fontSize: 15, fontWeight: 700, color: "#111" }}>📌 Select Farm Location</div>
            <div style={{ fontSize: 12, color: "#1a7a3a", fontWeight: 600, marginTop: 2 }}>
              🔍 Type your village / college / area name in the search bar below
            </div>
          </div>
        </div>

        <div style={{ position: "relative", flex: "0 0 420px" }}>
          <div ref={pickerMapRef} style={{ width: "100%", height: 420 }} />

          {/* ── Poor accuracy warning — shown on desktop/IP-based location ── */}
          {gpsStatus === "poor" && (
            <div style={{
              position: "absolute", top: 72, left: 12, right: 12, zIndex: 1001,
              background: "#fff3e0", border: "1px solid #ffb74d",
              borderRadius: 10, padding: "10px 14px",
              display: "flex", alignItems: "flex-start", gap: 8,
              boxShadow: "0 2px 8px rgba(0,0,0,.12)",
            }}>
              <span style={{ fontSize: 18, flexShrink: 0 }}>⚠️</span>
              <div>
                <div style={{ fontSize: 12.5, fontWeight: 700, color: "#e65100" }}>
                  Browser location is inaccurate
                  {locationAccuracy ? ` (±${locationAccuracy >= 1000 ? (locationAccuracy/1000).toFixed(1)+"km" : locationAccuracy+"m"})` : ""}
                </div>
                <div style={{ fontSize: 11.5, color: "#bf360c", marginTop: 2 }}>
                  Desktop browsers use IP/WiFi — not GPS. 🔍 Search your village, college or landmark above for exact location.
                </div>
              </div>
            </div>
          )}

          {/* Floating search bar — picker */}
          <div style={{ position: "absolute", top: 12, left: 12, right: 12, zIndex: 1000 }}>
            <div style={{
              display: "flex", alignItems: "center",
              background: "#fff", borderRadius: 14,
              padding: "0 14px",
              boxShadow: "0 4px 20px rgba(0,0,0,.18)",
              border: "1px solid #e4e4e4",
            }}>
              <span style={{ fontSize: 16, color: "#aaa", marginRight: 8 }}>🔍</span>
              <input
                ref={searchInputRef}
                value={searchQuery}
                onChange={e => handleSearchInput(e.target.value)}
                onFocus={() => searchResults.length > 0 && setShowSuggestions(true)}
                placeholder={SS.placeholder || "Search village, town, college, landmark…"}
                style={{
                  flex: 1, border: "none", outline: "none",
                  fontSize: 13.5, padding: "13px 0",
                  background: "transparent", color: "#222",
                }}
              />
              {searching && <span style={{ fontSize: 11, color: "#ccc", marginRight: 4 }}>…</span>}
              {searchQuery && (
                <button onClick={() => { setSearchQuery(""); setSearchResults([]); setShowSuggestions(false); }}
                  style={{ background: "none", border: "none", cursor: "pointer", color: "#bbb", fontSize: 17 }}>✕</button>
              )}
            </div>

            {showSuggestions && searchResults.length > 0 && (
              <div style={{
                position: "absolute", top: "calc(100% + 5px)", left: 0, right: 0,
                background: "#fff", borderRadius: 14, overflow: "hidden",
                boxShadow: "0 10px 30px rgba(0,0,0,.16)", zIndex: 9999,
                maxHeight: 260, overflowY: "auto",
              }}>
                {searchResults.map((r, i) => {
                  const a    = r.address || {};
                  const name = a.hamlet || a.village || a.town || a.city || r.display_name.split(",")[0];
                  const sub  = [a.county || a.district, a.state].filter(Boolean).join(", ");
                  return (
                    <div key={i} onClick={() => selectResult(r)}
                      style={{
                        display: "flex", alignItems: "center", gap: 12,
                        padding: "12px 16px", cursor: "pointer",
                        borderBottom: i < searchResults.length - 1 ? "1px solid #f2f2f2" : "none",
                      }}
                      onMouseEnter={e => e.currentTarget.style.background = "#f6fdf7"}
                      onMouseLeave={e => e.currentTarget.style.background = "#fff"}
                    >
                      <div style={{
                        width: 36, height: 36, borderRadius: 10,
                        background: "#e8f5e9", display: "flex",
                        alignItems: "center", justifyContent: "center",
                        fontSize: 18, flexShrink: 0,
                      }}>📍</div>
                      <div>
                        <div style={{ fontSize: 13.5, fontWeight: 700, color: "#1a1a1a" }}>{name}</div>
                        <div style={{ fontSize: 11.5, color: "#999", marginTop: 1 }}>{sub}</div>
                      </div>
                    </div>
                  );
                })}
              </div>
            )}
          </div>

          {/* Tile toggle */}
          <div style={{ position: "absolute", bottom: 52, left: 12, zIndex: 999, display: "flex", gap: 6 }}>
            {Object.entries(TILE_LAYERS).map(([key, layer]) => (
              <button key={key} onClick={() => setTileMode(key)} style={{
                padding: "5px 11px", borderRadius: 8, fontSize: 11.5, fontWeight: 600,
                border: "none", cursor: "pointer",
                background: tileMode === key ? "#1a7a3a" : "rgba(255,255,255,.93)",
                color: tileMode === key ? "#fff" : "#333",
                boxShadow: "0 2px 8px rgba(0,0,0,.18)",
              }}>{layer.label}</button>
            ))}
          </div>

          {/* GPS button */}
          <button onClick={handleGPS} disabled={gpsStatus === "loading"} style={{
            position: "absolute", bottom: 96, right: 12, zIndex: 999,
            background: gpsStatus === "done" ? "#1a7a3a" : gpsStatus === "error" ? "#b83232" : "#fff",
            color: gpsStatus === "idle" ? "#1a7a3a" : "#fff",
            border: "none", borderRadius: 12,
            padding: "10px 14px", fontSize: 12.5, fontWeight: 700,
            cursor: gpsStatus === "loading" ? "wait" : "pointer",
            boxShadow: "0 3px 12px rgba(0,0,0,.2)",
            display: "flex", alignItems: "center", gap: 5,
          }}>
            {gpsLabel[gpsStatus]}
          </button>

          {/* Center pin */}
          {pickerLoaded && (
            <div style={{
              position: "absolute", top: "50%", left: "50%",
              transform: `translate(-50%, -100%) ${pinMoving ? "translateY(-8px)" : ""}`,
              zIndex: 1000, pointerEvents: "none",
              transition: "transform 0.15s cubic-bezier(.4,0,.2,1)",
            }}>
              <div style={{
                position: "absolute", bottom: -4, left: "50%",
                transform: "translateX(-50%)",
                width: pinMoving ? 16 : 10, height: pinMoving ? 6 : 4,
                borderRadius: "50%", background: "rgba(0,0,0,.22)",
                filter: "blur(3px)", transition: "all .15s ease",
              }} />
              <div style={{ display: "flex", flexDirection: "column", alignItems: "center" }}>
                <div style={{
                  background: "#1a7a3a", color: "#fff",
                  padding: "7px 12px", borderRadius: 10,
                  fontSize: 12.5, fontWeight: 700,
                  boxShadow: "0 4px 16px rgba(0,0,0,.28)",
                  whiteSpace: "nowrap",
                  opacity: pinMoving ? 0.75 : 1, transition: "opacity .15s",
                }}>
                  {pinMoving ? "🚜 Moving…" : "📍 Your Farm Here"}
                </div>
                <div style={{ width: 2.5, height: 16, background: "#1a7a3a" }} />
                <div style={{
                  width: 10, height: 10, borderRadius: "50%",
                  background: "#1a7a3a", marginTop: -1,
                  boxShadow: "0 0 0 3px rgba(26,122,58,.3)",
                }} />
              </div>
            </div>
          )}

          {pickerLoaded && (
            <div style={{
              position: "absolute", top: "50%", left: "50%",
              transform: "translate(-50%,-50%)",
              pointerEvents: "none", zIndex: 999,
            }}>
              {[70, 38].map(sz => (
                <div key={sz} style={{
                  width: sz, height: sz, borderRadius: "50%",
                  border: "1px solid rgba(26,122,58,0.3)",
                  position: "absolute", top: "50%", left: "50%",
                  transform: "translate(-50%,-50%)",
                }} />
              ))}
            </div>
          )}
        </div>

        {/* Address & form panel */}
        <div style={{ background: "#fff", flex: 1, padding: "0 16px 30px", overflowY: "auto" }}>

          {/* Search tip banner — always shown, guides user to search */}
          <div style={{
            margin: "12px 0 10px", padding: "12px 14px", borderRadius: 12,
            background: "#e8f5e9", border: "1px solid #a5d6a7",
            display: "flex", alignItems: "flex-start", gap: 10,
          }}>
            <span style={{ fontSize: 20, flexShrink: 0 }}>🔍</span>
            <div>
              <div style={{ fontSize: 13, fontWeight: 700, color: "#1a3a25" }}>
                Search for your exact location
              </div>
              <div style={{ fontSize: 11.5, color: "#3a6e50", marginTop: 2, lineHeight: 1.5 }}>
                Type <b>Pottapalaiyam</b>, <b>SRM Madurai</b>, your village name or any nearby landmark
                in the search bar above → select the result → then slide the map pin exactly onto your farm.
              </div>
            </div>
          </div>

          {/* Detected address card */}
          <div style={{
            marginBottom: 14, padding: "12px 14px", borderRadius: 12,
            background: "#f7fdf9", border: "1px solid #c8e6c9",
            display: "flex", alignItems: "flex-start", gap: 10,
          }}>
            <div style={{ fontSize: 22, marginTop: 2 }}>📍</div>
            <div style={{ flex: 1, minWidth: 0 }}>
              {rgLoading ? (
                <div style={{ color: "#aaa", fontSize: 12.5, display: "flex", alignItems: "center", gap: 7 }}>
                  <span style={{
                    display: "inline-block", width: 11, height: 11, borderRadius: "50%",
                    border: "2px solid #1a7a3a", borderTopColor: "transparent",
                    animation: "spin .7s linear infinite",
                  }} />
                  <style>{`@keyframes spin{to{transform:rotate(360deg)}}`}</style>
                  Reading map position…
                </div>
              ) : addr ? (
                <>
                  <div style={{ fontSize: 14, fontWeight: 700, color: "#133320" }}>{addr.line1}</div>
                  <div style={{ fontSize: 12, color: "#3a6e50", marginTop: 1 }}>{addr.line2}</div>
                  <div style={{ fontSize: 11.5, color: "#888", marginTop: 1 }}>{addr.line3}</div>
                </>
              ) : (
                <div style={{ color: "#aaa", fontSize: 12.5 }}>
                  Search above or slide the map — address will appear here
                </div>
              )}
              {pickerCoords && (
                <div style={{ fontSize: 10, color: "#bbb", marginTop: 4, fontFamily: "monospace" }}>
                  {pickerCoords.lat.toFixed(6)}, {pickerCoords.lon.toFixed(6)}
                </div>
              )}
            </div>
            <button onClick={handleGPS} title="Try device GPS (works on mobile)" style={{
              flexShrink: 0, background: gpsStatus === "loading" ? "#e8f5e9" : "#f5f5f5",
              border: "1px solid #ddd", borderRadius: 8, padding: "7px 10px",
              fontSize: 11, fontWeight: 700, color: "#666", cursor: "pointer",
              lineHeight: 1.3, textAlign: "center",
            }}>
              📡<br />GPS
            </button>
          </div>
          <div style={{ fontSize: 14, fontWeight: 700, color: "#111", marginBottom: 10 }}>Farm Details</div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 10, marginBottom: 10 }}>
            <Input label={TX.plotName} value={formFarm.name}
              onChange={e => setFormFarm(p => ({ ...p, name: e.target.value }))}
              placeholder="e.g. North Field" />
            <Input label={TX.crop} value={formFarm.crop}
              onChange={e => setFormFarm(p => ({ ...p, crop: e.target.value }))}
              options={CROP_OPTIONS} />
            <Input label={`${TX.area} (${TX.acres})`} value={formFarm.size} type="number"
              onChange={e => setFormFarm(p => ({ ...p, size: e.target.value }))}
              placeholder="e.g. 2.5" />
            <Input label={TX.soilType} value={formFarm.soilType}
              onChange={e => setFormFarm(p => ({ ...p, soilType: e.target.value }))}
              options={SOIL_TYPES} />
            <div style={{ gridColumn: "span 2" }}>
              <Input label={TX.status} value={formFarm.status}
                onChange={e => setFormFarm(p => ({ ...p, status: e.target.value }))}
                options={FARM_STATUSES} />
            </div>
          </div>

          <div style={{ display: "flex", gap: 10, marginTop: 6 }}>
            <button
              onClick={confirmSave}
              disabled={!formFarm.name || !pickerCoords}
              style={{
                flex: 1, padding: "15px", borderRadius: 13, border: "none",
                background: formFarm.name && pickerCoords ? "#1a7a3a" : "#d0d0d0",
                color: "#fff", fontSize: 15, fontWeight: 700,
                cursor: formFarm.name && pickerCoords ? "pointer" : "not-allowed",
                boxShadow: formFarm.name && pickerCoords ? "0 5px 14px rgba(26,122,58,.35)" : "none",
                transition: "all .2s",
              }}
            >
              ✅ Confirm Location &amp; Save Farm
            </button>
            <button onClick={() => setPickerOpen(false)} style={{
              padding: "15px 20px", borderRadius: 13,
              border: "1px solid #ddd", background: "#fff",
              fontSize: 14, fontWeight: 600, color: "#666", cursor: "pointer",
            }}>Cancel</button>
          </div>
        </div>
      </div>
    );
  }

  // ═══════════════════════════════════════════════════════════════════════════
  // MAIN VIEW
  // ═══════════════════════════════════════════════════════════════════════════
  return (
    <div style={{ padding: 20 }}>

      {/* ── ANALYSIS PANEL (inline — no early return so map div stays mounted) ── */}
      {analyseFarm && (
        <div style={{ maxWidth: 700 }}>
          {/* Back + title */}
          <div style={{ display: "flex", alignItems: "center", gap: 10, marginBottom: 18 }}>
            <button
              onClick={() => setAnalyseFarm(null)}
              style={{
                background: "none", border: "none", fontSize: 22,
                cursor: "pointer", color: C.text || "#222", padding: "2px 6px 2px 0",
              }}
            >←</button>
            <div>
              <h2 style={{ fontSize: 18, fontWeight: 700, color: C.text || "#222", margin: 0 }}>
                📊 Farm Input Analysis
              </h2>
              <div style={{ fontSize: 12, color: C.muted || "#888", marginTop: 2 }}>
                {analyseFarm.name} · {analyseFarm.crop} · {analyseFarm.size} {TX.acres}
              </div>
            </div>
          </div>

          {/* Classification banner */}
          <div style={{
            background: "linear-gradient(135deg,#1a7a3a,#0e4a22)",
            borderRadius: 14, padding: "16px 20px", marginBottom: 16,
            display: "flex", justifyContent: "space-between", alignItems: "center",
          }}>
            <div>
              <div style={{ fontSize: 11, color: "rgba(255,255,255,.6)" }}>Field Classification</div>
              <div style={{ fontSize: 16, fontWeight: 700, color: "#fff", marginTop: 3 }}>
                {analysisReq ? analysisReq.sizeLabel : "Enter field size to analyse"}
              </div>
            </div>
            <div style={{ textAlign: "right" }}>
              <div style={{ fontSize: 11, color: "rgba(255,255,255,.6)" }}>Crop Duration</div>
              <div style={{ fontSize: 18, fontWeight: 700, color: "#5de87a", marginTop: 3 }}>
                {analysisReq ? `${analysisReq.duration} days` : "—"}
              </div>
            </div>
          </div>

          {!analysisReq ? (
            <div style={{
              background: "#fff8e1", border: "1px solid #ffe082",
              borderRadius: 12, padding: 18, fontSize: 13, color: "#7a5800", textAlign: "center",
            }}>
              ⚠️ No land size recorded. Edit the farm and enter the size in acres to see the full analysis.
            </div>
          ) : (
            <>
              {/* 3-chip summary */}
              <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr 1fr", gap: 10, marginBottom: 14 }}>
                {[
                  { emoji: "🌱", label: "Seeds Needed",  val: analysisReq.seeds,                   bg: "#277d2e", col: "#1a7a3a" },
                  { emoji: "💧", label: "Water / Day",   val: `${analysisReq.waterPerDay} kL`,      bg: "#e3f2fd", col: "#1565c0" },
                  { emoji: "📐", label: "Plant Spacing", val: analysisReq.spacing,                  bg: "#f3e5f5", col: "#6a1b9a" },
                ].map(c => (
                  <div key={c.label} style={{ background: c.bg, borderRadius: 12, padding: "12px 10px", textAlign: "center" }}>
                    <div style={{ fontSize: 22 }}>{c.emoji}</div>
                    <div style={{ fontSize: 10.5, color: "#888", marginTop: 4 }}>{c.label}</div>
                    <div style={{ fontSize: 13, fontWeight: 700, color: c.col, marginTop: 3 }}>{c.val}</div>
                  </div>
                ))}
              </div>

              {/* Seeds */}
              <div style={{ background: "#fff", borderRadius: 12, padding: "14px 16px", marginBottom: 12, border: `1px solid ${C.border || "#eee"}` }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#1a7a3a", marginBottom: 4 }}>🌱 Seeds / Planting Material</div>
                <AnalysisROW label="Quantity Required"   val={analysisReq.seeds} />
                <AnalysisROW label="Estimated Seed Cost" val={`₹${analysisReq.seedCost.toLocaleString("en-IN")}`} color="#c87010" />
              </div>

              {/* Fertilisers */}
              <div style={{ background: "#fff", borderRadius: 12, padding: "14px 16px", marginBottom: 12, border: `1px solid ${C.border || "#eee"}` }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#1a7a3a", marginBottom: 4 }}>🧪 Chemical Fertilisers</div>
                <AnalysisROW label="Urea (Nitrogen)"  val={`${analysisReq.urea} kg`}  sub={`${analysisReq.totalN} kg N — split into 3 applications`} />
                <AnalysisROW label="DAP (Phosphorus)" val={`${analysisReq.dap} kg`}   sub={`${analysisReq.totalP} kg P — apply at sowing`} />
                <AnalysisROW label="MOP (Potassium)"  val={`${analysisReq.mop} kg`}   sub={`${analysisReq.totalK} kg K — apply at sowing`} />
                <AnalysisROW label="Fertiliser Cost"  val={`₹${analysisReq.fertCost.toLocaleString("en-IN")}`} color="#c87010" />
              </div>

              {/* Organic */}
              <div style={{ background: "#fff", borderRadius: 12, padding: "14px 16px", marginBottom: 12, border: `1px solid ${C.border || "#eee"}` }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#1a7a3a", marginBottom: 4 }}>🍃 Organic Manure (FYM)</div>
                <AnalysisROW label="Quantity Required"  val={`${analysisReq.organic} tonnes`} />
                <AnalysisROW label="No. of 50 kg Bags" val={`${analysisReq.organicBags} bags`} sub="1 tonne ≈ 20 bags of 50 kg" />
                <AnalysisROW label="Organic Cost"       val={`₹${analysisReq.organicCost.toLocaleString("en-IN")}`} color="#c87010" />
              </div>

              {/* Water */}
              <div style={{ background: "#e3f2fd", borderRadius: 12, padding: "14px 16px", marginBottom: 12, border: "1px solid #90caf9" }}>
                <div style={{ fontSize: 13, fontWeight: 700, color: "#1565c0", marginBottom: 4 }}>💧 Water Requirement</div>
                <AnalysisROW label="Daily Irrigation"   val={`${analysisReq.waterPerDay} kL/day`} />
                <AnalysisROW
                  label="Total Season Water"
                  val={`${+(analysisReq.waterPerDay * analysisReq.duration).toFixed(0)} kL`}
                  sub={`Over ${analysisReq.duration}-day crop period`}
                />
              </div>

              {/* Total cost */}
              <div style={{
                background: "linear-gradient(135deg,#fff8e1,#fff3cd)",
                borderRadius: 12, padding: "16px 20px", marginBottom: 14,
                border: "1px solid #ffe082",
                display: "flex", justifyContent: "space-between", alignItems: "center",
              }}>
                <div>
                  <div style={{ fontSize: 13, color: "#7a5800", fontWeight: 600 }}>Total Estimated Input Cost</div>
                  <div style={{ fontSize: 11, color: "#aaa", marginTop: 2 }}>Seeds + Fertiliser + Organic Manure</div>
                </div>
                <div style={{ fontSize: 22, fontWeight: 800, color: "#c87010" }}>
                  ₹{analysisReq.totalCost.toLocaleString("en-IN")}
                </div>
              </div>

              <div style={{ fontSize: 11, color: C.muted || "#888", textAlign: "center", lineHeight: 1.7, padding: "0 8px 16px" }}>
                * Quantities follow standard agronomic recommendations for Tamil Nadu. Actual needs vary by soil health, variety and season. Consult your local Agricultural Officer for site-specific advice.
              </div>
            </>
          )}
        </div>
      )}

      {/* ── MAIN MAP VIEW — hidden via display:none when analysis is open ── */}
      {/* display:none keeps the mapRef div in the DOM so Leaflet never loses its container */}
      <div style={{ display: analyseFarm ? "none" : "block" }}>

      {/* Header */}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 12 }}>
        <div>
          <h1 style={{ fontSize: 22, fontWeight: 600, color: C.text, margin: 0 }}>🗺️ {TX.title}</h1>
          <p style={{ color: C.muted, fontSize: 13, margin: "4px 0 0" }}>{TX.subtitle}</p>
        </div>
        <div style={{ display: "flex", gap: 8 }}>
          <button onClick={() => setTileMode(m => m === "street" ? "satellite" : "street")} style={{
            padding: "8px 14px", borderRadius: 8,
            border: `1px solid ${C.border || "#ddd"}`,
            background: tileMode === "satellite" ? "#1a1a2e" : "#fff",
            color: tileMode === "satellite" ? "#7dd87d" : C.text,
            fontSize: 12.5, fontWeight: 600, cursor: "pointer",
          }}>
            {TILE_LAYERS[tileMode === "satellite" ? "street" : "satellite"].label}
          </button>
          <Btn onClick={() => setPickerOpen(true)} variant="primary">{TX.addPlot}</Btn>
        </div>
      </div>

      {/* ── NEW: Main map search bar ──────────────────────────────────────── */}
      <div style={{ position: "relative", marginBottom: 12, maxWidth: 420 }}>
        <div style={{
          display: "flex", alignItems: "center",
          background: "#fff", borderRadius: 12,
          border: `1.5px solid ${mainSearch ? C.bg2 : C.border}`,
          padding: "0 14px",
          boxShadow: mainSearch ? "0 2px 12px rgba(26,122,58,.15)" : "0 1px 4px rgba(0,0,0,.08)",
          transition: "border-color 0.2s, box-shadow 0.2s",
        }}>
          <span style={{ fontSize: 16, color: mainSearch ? C.bg2 : "#bbb", marginRight: 8, flexShrink: 0 }}>🔍</span>
          <input
            value={mainSearch}
            onChange={e => handleMainSearch(e.target.value)}
            onKeyDown={e => {
              if (e.key === "Enter" && mainResults.length > 0) selectMainResult(mainResults[0]);
            }}
            onFocus={() => mainResults.length > 0 && setMainShowSuggest(true)}
            onBlur={() => setTimeout(() => setMainShowSuggest(false), 180)}
            placeholder={SS.placeholder}
            style={{
              flex: 1, border: "none", outline: "none",
              fontSize: 13.5, padding: "11px 0",
              background: "transparent", color: "#222",
            }}
          />
          {mainSearching && (
            <span style={{ fontSize: 12, color: C.muted, marginRight: 6 }}>{SS.searching}</span>
          )}
          {mainSearch && !mainSearching && (
            <button
              onClick={() => { setMainSearch(""); setMainResults([]); setMainShowSuggest(false); setMainFlownTo(null); }}
              style={{ background: "none", border: "none", cursor: "pointer", color: "#bbb", fontSize: 17, padding: "0 0 0 6px" }}
            >✕</button>
          )}
        </div>

        {/* "Navigating to" toast */}
        {mainFlownTo && (
          <div style={{
            marginTop: 6, padding: "6px 12px",
            background: "#e8f5e9", borderRadius: 8,
            fontSize: 12.5, color: C.bg2, fontWeight: 500,
            display: "flex", alignItems: "center", gap: 6,
          }}>
            ✅ {SS.flyingTo}: <strong>{mainFlownTo}</strong>
          </div>
        )}

        {/* Suggestions dropdown */}
        {mainShowSuggest && mainResults.length > 0 && (
          <div style={{
            position: "absolute", top: "calc(100% + 4px)", left: 0, right: 0,
            background: "#fff", borderRadius: 12,
            border: `1px solid ${C.border}`,
            boxShadow: "0 8px 24px rgba(0,0,0,.14)",
            zIndex: 9999, overflow: "hidden",
            maxHeight: 280, overflowY: "auto",
          }}>
            {mainResults.map((r, i) => {
              const a    = r.address || {};
              const name = a.hamlet || a.village || a.town || a.city || r.display_name.split(",")[0];
              const sub  = [a.county || a.district, a.state_district, a.state].filter(Boolean).join(", ");
              const type = a.hamlet ? "🏘️" : a.village ? "🌾" : a.town ? "🏙️" : a.city ? "🌆" : "📍";
              return (
                <div
                  key={i}
                  onMouseDown={() => selectMainResult(r)}  // mouseDown fires before onBlur
                  style={{
                    display: "flex", alignItems: "center", gap: 12,
                    padding: "11px 16px", cursor: "pointer",
                    borderBottom: i < mainResults.length - 1 ? `1px solid ${C.border}` : "none",
                    background: "#fff", transition: "background 0.1s",
                  }}
                  onMouseEnter={e => e.currentTarget.style.background = C.pale}
                  onMouseLeave={e => e.currentTarget.style.background = "#fff"}
                >
                  <div style={{
                    width: 34, height: 34, borderRadius: 9,
                    background: C.pale, display: "flex",
                    alignItems: "center", justifyContent: "center",
                    fontSize: 17, flexShrink: 0,
                  }}>
                    {type}
                  </div>
                  <div style={{ minWidth: 0 }}>
                    <div style={{ fontSize: 13.5, fontWeight: 600, color: C.text, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                      {name}
                    </div>
                    <div style={{ fontSize: 11.5, color: C.muted, marginTop: 1, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                      {sub}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* No results */}
        {mainShowSuggest && !mainSearching && mainResults.length === 0 && mainSearch.length >= 2 && (
          <div style={{
            position: "absolute", top: "calc(100% + 4px)", left: 0, right: 0,
            background: "#fff", borderRadius: 10,
            border: `1px solid ${C.border}`,
            padding: "14px 16px", fontSize: 13,
            color: C.muted, textAlign: "center",
            boxShadow: "0 4px 12px rgba(0,0,0,.08)", zIndex: 9999,
          }}>
            {SS.notFound} — try a nearby town or district name
          </div>
        )}
      </div>

      {/* Map + Panel */}
      <div style={{ display: "grid", gridTemplateColumns: "1fr 300px", gap: 14 }}>

        <Card style={{ padding: 0, overflow: "hidden", position: "relative" }}>
          {!loaded && (
            <div style={{ height: 480, display: "flex", alignItems: "center", justifyContent: "center", color: C.muted }}>
              {TX.loading}
            </div>
          )}
          <div ref={mapRef} style={{ height: 480, display: loaded ? "block" : "none" }} />
          {loaded && (
            <div style={{ position: "absolute", bottom: 12, left: 12, zIndex: 999, display: "flex", gap: 6 }}>
              {Object.entries(TILE_LAYERS).map(([key, layer]) => (
                <button key={key} onClick={() => setTileMode(key)} style={{
                  padding: "5px 10px", borderRadius: 6, fontSize: 11.5, fontWeight: 600,
                  border: "none", cursor: "pointer",
                  background: tileMode === key ? "#1a7a3a" : "rgba(255,255,255,.9)",
                  color: tileMode === key ? "#fff" : "#333",
                  boxShadow: "0 2px 6px rgba(0,0,0,.2)",
                }}>{layer.label}</button>
              ))}
            </div>
          )}
        </Card>

        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          <Card style={{ padding: 12 }}>
            <div style={{ fontSize: 12.5, fontWeight: 600, color: C.text, marginBottom: 8 }}>
              {TX.yourFarms} ({farms.length})
            </div>
            {farms.length === 0 && (
              <div style={{ fontSize: 12, color: C.muted, textAlign: "center", padding: "16px 0" }}>
                {TX.noFarms}<br />
                <span style={{ fontSize: 11.5 }}>{TX.addFirst}</span>
              </div>
            )}
            {farms.map(f => (
              <div key={f.id} style={{ padding: "9px 0", borderBottom: `1px solid ${C.border}` }}>
                <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                  <div style={{ flex: 1, minWidth: 0, marginRight: 8 }}>
                    <div style={{ fontSize: 13, fontWeight: 600, color: C.text }}>{f.name}</div>
                    <div style={{ fontSize: 11.5, color: C.muted, marginTop: 1 }}>
                      {f.crop} · {f.size} {TX.acres} · {f.soilType}
                    </div>
                    {f.address && (
                      <div style={{ fontSize: 11, color: "#888", marginTop: 2, lineHeight: 1.4 }}>📍 {f.address}</div>
                    )}
                    <div style={{ fontSize: 10, color: "#ccc", marginTop: 2, fontFamily: "monospace" }}>
                      {f.lat?.toFixed(5)}, {f.lon?.toFixed(5)}
                    </div>
                  </div>
                  <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 5, flexShrink: 0 }}>
                    <Badge color={statusColor[f.status] || C.muted} bg={statusBg[f.status] || C.pale}>
                      {f.status}
                    </Badge>
                    {confirmRemove === f.id ? (
                      <div style={{ display: "flex", gap: 4 }}>
                        <button onClick={() => removeFarm(f.id)} style={{
                          padding: "3px 9px", borderRadius: 6, border: "none",
                          background: "#b83232", color: "#fff", fontSize: 11, fontWeight: 700, cursor: "pointer",
                        }}>Yes, Delete</button>
                        <button onClick={() => setConfirmRemove(null)} style={{
                          padding: "3px 8px", borderRadius: 6,
                          border: "1px solid #ddd", background: "#fff",
                          fontSize: 11, cursor: "pointer", color: "#555",
                        }}>No</button>
                      </div>
                    ) : (
                      <div style={{ display: "flex", gap: 4 }}>
                        <button onClick={() => setAnalyseFarm(f)} style={{
                          padding: "3px 9px", borderRadius: 6,
                          border: "1px solid #b2dfdb", background: "#e8f5e9",
                          color: "#1a7a3a", fontSize: 11, fontWeight: 600, cursor: "pointer",
                        }}>📊 Analyse</button>
                        <button onClick={() => setConfirmRemove(f.id)} style={{
                          padding: "3px 9px", borderRadius: 6,
                          border: "1px solid #f0c0c0", background: "#fff8f8",
                          color: "#b83232", fontSize: 11, fontWeight: 500, cursor: "pointer",
                        }}>🗑 Remove</button>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))}
          </Card>

          <Card style={{ padding: 12, background: C.pale }}>
            <div style={{ fontSize: 12.5, fontWeight: 600, color: C.text, marginBottom: 8 }}>{TX.fieldConds}</div>
            {fieldConditions.map(r => (
              <div key={r.label} style={{ display: "flex", justifyContent: "space-between", marginBottom: 6, fontSize: 12.5 }}>
                <span style={{ color: C.muted }}>{r.label}</span>
                <span style={{ fontWeight: 500, color: r.risk === "High" ? C.red : r.risk === "Medium" ? C.orange : C.text }}>
                  {r.val}
                </span>
              </div>
            ))}
          </Card>

          <Card style={{ padding: 12, background: "linear-gradient(135deg,#0e3a1c,#062010)", border: "none" }}>
            <div style={{ fontSize: 13, fontWeight: 600, color: "#fff", marginBottom: 6 }}>{TX.ndvi}</div>
            <div style={{ fontSize: 12, color: "rgba(255,255,255,.7)", lineHeight: 1.6 }}>
              Crop health index: <span style={{ color: "#5de87a", fontWeight: 600 }}>0.72 (Good)</span><br />
              Last satellite pass: Today 10:32 AM<br />
              Cloud cover: 18%
            </div>
            <div style={{ marginTop: 10, display: "flex", gap: 6 }}>
              {[{ c: "#1a7a3a", l: "Healthy" }, { c: "#c87010", l: "Stress" }, { c: "#b83232", l: "Alert" }].map(s => (
                <div key={s.l} style={{ display: "flex", alignItems: "center", gap: 4, fontSize: 10.5, color: "rgba(255,255,255,.6)" }}>
                  <div style={{ width: 8, height: 8, borderRadius: 2, background: s.c }} />{s.l}
                </div>
              ))}
            </div>
          </Card>
        </div>
      </div>
      </div>{/* end main map view */}
    </div>
  );
}

export default FarmMap;
